(function(){var loadHandler=window['sl_{467E2788-00FD-4FCC-960D-56BC8487CF6D}'];loadHandler&&loadHandler(39, '<div id="spr0_13a129f4"><div id="spr1_13a129f4" class="kern slide"><img id="img2_13a129f4" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/><div id="spr3_13a129f4" style="left:1192px;"><a id="hl0_13a129f4" href="#" onclick="document.getElementById(\'coreSpr_10543692\').getCore().processTriggerEffect(this);document.getElementById(\'coreSpr_10543692\').getCore().gotoFirstSlide(this);return false;"><img id="img0_13a129f4" src="data:image/png;base64," width="87" height="88" alt="" style="left:0.017px;top:0.102px;"/></a></div><div id="spr4_13a129f4" style="left:968.816px;top:11.687px;"><img id="img1_13a129f4" src="data:image/png;base64," width="247" height="60" alt="A close-up of a pen  AI-generated content may be incorrect." style="left:-0.071px;top:-0.093px;"/></div></div><div id="spr2_13a129f4" class="kern slide"><div id="spr5_13a129f4" style="left:146.122px;top:18.444px;"><div style="width:0px;"><span id="txt0_13a129f4" data-width="940.375000" style="left:38.823px;top:-18.43px;">IMPORTANCE OF MANAGING DRAINAGE BASINS AND</span></div><div style="width:0px;"><span id="txt1_13a129f4" data-width="359.078125" style="left:328.663px;top:16.13px;">CATCHMENT AREAS</span></div></div><div id="spr6_13a129f4" style="left:-0.192px;top:87.914px;"><div style="width:0px;"><span id="txt2_13a129f4" class="nokern relpos" dir="auto" style="left:9.6px;top:1.407px;">•</span> <span id="txt3_13a129f4" class="relpos" data-width="1209.304688" style="left:20.53px;top:-3.853px;">The rainwater in a drainage basin or catchment area collects as rivers, lakes and</span></div><div style="width:0px;"><span id="txt4_13a129f4" data-width="405.690094" style="left:33.6px;top:36.467px;">reservoirs of groundwater.</span></div><div style="width:0px;"><span id="txt5_13a129f4" class="nokern relpos" dir="auto" style="left:9.6px;top:94.611px;">•</span> <span id="txt6_13a129f4" class="relpos" data-width="154.328125" style="left:20.53px;top:89.351px;">There are </span> <span id="txt7_13a129f4" class="relpos" data-width="361.575500" style="left:20.523px;top:89.351px;">THREE MAIN REASONS </span> <span id="txt8_13a129f4" class="relpos" data-width="125.343742" style="left:20.516px;top:89.351px;">why we </span></div><div style="width:0px;"><span id="txt9_13a129f4" data-width="477.257782" style="left:672.473px;top:89.351px;">must manage catchment areas:</span></div><div style="width:0px;"><span id="txt10_13a129f4" class="nokern relpos" data-width="28.346354" dir="auto" style="left:9.6px;top:196.658px;">1.</span> <span id="txt11_13a129f4" class="relpos" data-width="502.341125" style="left:35.254px;top:196.658px;">Our river systems are part of the </span> <span id="txt12_13a129f4" class="relpos" data-width="194.997391" style="left:35.247px;top:196.658px;">water cycle. </span> <span id="txt13_13a129f4" class="relpos" data-width="475.963531" style="left:35.24px;top:196.658px;">All water bodies are linked, e.g.</span></div><div style="width:0px;"><span id="txt14_13a129f4" data-width="1205.476563" style="left:63.6px;top:237.747px;">groundwater feeds into rivers, and rivers feed into lakes and wetlands. The way</span></div><div style="width:0px;"><span id="txt15_13a129f4" data-width="880.213501" style="left:63.6px;top:278.068px;">we use the land has a dramatic impact on the water cycle.</span></div><div style="width:0px;"><span id="txt16_13a129f4" class="nokern relpos" data-width="28.346354" dir="auto" style="left:9.6px;top:330.951px;">2.</span> <span id="txt17_13a129f4" class="relpos" data-width="358.549469" style="left:35.254px;top:330.951px;">Our river systems are a </span> <span id="txt18_13a129f4" class="relpos" data-width="130.046875" style="left:35.247px;top:330.951px;">habitat, </span> <span id="txt19_13a129f4" class="relpos" data-width="241.700516" style="left:35.24px;top:330.951px;">and function as </span> <span id="txt20_13a129f4" class="relpos" data-width="197.695313" style="left:35.234px;top:330.951px;">ecosystems: </span> <span id="txt21_13a129f4" class="relpos" data-width="176.841141" style="left:35.227px;top:330.951px;">A river links</span></div><div style="width:0px;"><span id="txt22_13a129f4" data-width="651.710938" style="left:63.6px;top:372.041px;">together many ecosystems in a catchment.</span></div><div style="width:0px;"><span id="txt23_13a129f4" class="nokern relpos" data-width="28.346354" dir="auto" style="left:9.6px;top:424.925px;">3.</span> <span id="txt24_13a129f4" class="relpos" data-width="1081.846313" style="left:35.254px;top:424.925px;">Our river systems are a resource: Water is essential for our survival and</span></div><div style="width:0px;"><span id="txt25_13a129f4" data-width="808.682251" style="left:63.6px;top:466.014px;">wellbeing, and for social and economic development.</span></div><div style="width:0px;"><span id="txt26_13a129f4" data-width="1022.145813" style="left:63.6px;top:506.334px;">We use our water resources for agriculture, industry, domestic use,</span></div><div style="width:0px;"><span id="txt27_13a129f4" data-width="546.875000" style="left:63.6px;top:546.654px;">hydroelectric power and recreation.</span></div></div></div></div>', '{"s":[]}');})();